def generate_R(x, y, N=191):
    """Generates the set R closed under doubling and addition, starting with {x, y}."""
    if x > N or y > N:
        return set()

    R = {x, y}
    changed = True

    while changed:
        changed = False
        new_elements = set()

        # Rule (i): Doubling
        for r in list(R):
            r2 = 2 * r
            if r2 <= N and r2 not in R:
                new_elements.add(r2)

        # Rule (ii): Addition
        # We only need to check pairs involving at least one element that is already in R,
        # but for full closure check, we iterate over all pairs in R.
        # Optimization: Since addition is commutative, we check r1 + r2 where r1 <= r2.
        R_list = sorted(list(R))
        for i in range(len(R_list)):
            for j in range(i, len(R_list)):
                r1 = R_list[i]
                r2 = R_list[j]
                sum_val = r1 + r2
                if sum_val <= N and sum_val not in R:
                    new_elements.add(sum_val)

        if new_elements:
            R.update(new_elements)
            changed = True

    return R

# Test cases based on the task request: small x and y.
test_pairs = [
    (1, 2),  # Should be 191
    (2, 3),
    (3, 4),
    (2, 4),
    (4, 4),
    (5, 7),
    (10, 20)
]

results = {}
for x, y in test_pairs:
    R = generate_R(x, y)
    size = len(R)
    sum_R = sum(R)
    results[(x, y)] = {'size': size, 'sum': sum_R}

print("--- Test Results ---")
for pair, data in results.items():
    print(f"Pair {pair}: Size={data['size']}, Sum(R)={data['sum']}")

# Find all pairs satisfying |R| >= 95 (only checking the test set for now)
large_R_pairs = {pair: data for pair, data in results.items() if data['size'] >= 95}
print("\n--- Pairs with Size >= 95 ---")
if large_R_pairs:
    for pair, data in large_R_pairs.items():
        print(f"Pair {pair}: Size={data['size']}, Sum(R)={data['sum']}")
else:
    print("None of the initial test pairs met the size criteria.")
